insert into public.catalog_templates (category, title_nb, title_en, body_nb, body_en, difficulty, points) values
  ('social', 'Si god morgen til noen du sjelden snakker med', 'Say good morning to someone you rarely talk to', 'Ta initiativ til en liten hilsen: på gangen, i heisen eller i chatten. Bare et smil og et «god morgen, hvordan går det?» gjør dagen litt lysere.', 'Take the first step with a small greeting: in the corridor, the lift or the chat. A smile and a “good morning, how is it going?” makes the day a little brighter.', 1, 10),
  ('social', 'Ta en kaffe- eller tepause uten jobbprat', 'Take a coffee or tea break without work talk', 'Ta en pause sammen med en kollega, fysisk eller på video, og snakk om alt annet enn jobb. Været, helgeplaner, en serie dere liker: hva som helst går.', 'Have a break with a colleague, in person or on video, and talk about anything but work. The weather, weekend plans, a show you both like: anything goes.', 1, 10),
  ('social', 'Del et bilde av noe fint du så i dag', 'Share a photo of something nice you saw today', 'Legg ut et bilde i teamets chat av noe fint du la merke til på veien: frost på en vindusrute, en vakker himmel, en lykt som lyser i mørket.', 'Post a photo in the team chat of something nice you noticed on the way: frost on a window, a beautiful sky, a lantern glowing in the dark.', 1, 10),
  ('social', 'Spør en kollega hva de gleder seg til', 'Ask a colleague what they look forward to', 'Spør en kollega hva de ser frem til i desember. Det kan være stort eller smått, og de trenger ikke svare hvis de ikke vil. Lytt, og del gjerne ditt eget svar.', 'Ask a colleague what they are looking forward to in December. It can be big or small, and they do not have to answer if they would rather not. Listen, and share your own if you like.', 1, 10),
  ('social', 'Spis lunsj med noen du ikke pleier å sitte sammen med', 'Have lunch with someone you do not usually sit with', 'Sett deg ved et annet bord enn vanlig, eller ta en videolunsj med en kollega fra et annet team. Nye samtaler starter ofte med et enkelt «kan jeg sitte her?».', 'Sit at a different table than usual, or have a video lunch with a colleague from another team. New conversations often start with a simple “may I join you?”.', 1, 10),
  ('social', 'Ta en 15 minutters tur med en kollega', 'Go for a 15-minute walk with a colleague', 'Foreslå en kort spasertur, eller en telefonprat med hver deres tur hvis dere jobber hjemmefra. Frisk luft og bevegelse gir gode samtaler.', 'Suggest a short walk, or a phone call with each of you out walking if you work from home. Fresh air and movement make for good conversations.', 2, 20),
  ('social', 'Følg opp noe en kollega har fortalt deg', 'Follow up on something a colleague told you', 'Husk en liten ting en kollega har nevnt, som en tur, et prosjekt eller en ny hobby, og spør hvordan det gikk. Det viser at du lyttet.', 'Remember a small thing a colleague mentioned, such as a trip, a project or a new hobby, and ask how it went. It shows you were listening.', 2, 20),
  ('social', 'Start «ukens spørsmål» i teamets chat', 'Start a “question of the week” in the team chat', 'Still et lett spørsmål alle kan svare på, for eksempel «hva er det beste du har spist i år?». Svar på minst to av de andre svarene.', 'Ask a light question everyone can answer, for example “what is the best thing you have eaten this year?”. Reply to at least two of the other answers.', 2, 20),
  ('social', 'Introduser deg for noen i et annet team', 'Introduce yourself to someone on another team', 'Finn noen du ikke kjenner på et annet team, og si hei. Fortell kort hva du jobber med, og spør hva de holder på med.', 'Find someone you do not know on another team and say hello. Briefly say what you work on, and ask what they are working on.', 2, 20),
  ('social', 'Ta en liten spillpause med en kollega', 'Play a quick game with a colleague', 'Spill en runde med noe enkelt i en kort pause: sjakk, ordspill, en quiz eller et kryssord. Det trenger ikke ta mer enn ti minutter.', 'Play a round of something simple during a short break: chess, a word game, a quiz or a crossword. It does not need to take more than ten minutes.', 2, 20),
  ('social', 'Arranger en felles pause for minst tre', 'Organise a shared break for at least three people', 'Inviter minst tre kollegaer til en felles pause på 20 minutter, fysisk eller på video. Ingen agenda, bare tid til å være sammen.', 'Invite at least three colleagues to a 20-minute break together, in person or on video. No agenda, just time to be together.', 3, 30),
  ('social', 'Sett i gang en lunsjrunde', 'Set up a lunch round', 'Inviter to eller tre kollegaer som vanligvis ikke spiser sammen til en felles lunsj denne uken. Velg gjerne en dag da alle kan, og husk de som jobber hjemmefra.', 'Invite two or three colleagues who do not usually eat together to a shared lunch this week. Pick a day that suits everyone, and remember those working from home.', 3, 30),
  ('kindness', 'Si takk og fortell hva du setter pris på', 'Say thank you and say what you appreciated', 'Si takk til en kollega, og nevn konkret hva du satte pris på. «Takk for at du hjalp meg med tabellen» varmer mer enn bare «takk».', 'Thank a colleague and be specific about what you appreciated. “Thanks for helping me with the table” warms more than a plain “thanks”.', 1, 10),
  ('kindness', 'Gi en oppriktig ros for arbeidet noen gjorde', 'Give a sincere compliment on someone''s work', 'Fortell en kollega hva du syns de fikk til, og hvorfor. Hold deg til innsatsen og resultatet, ikke utseende.', 'Tell a colleague what you think they did well, and why. Keep to the effort and the result, not appearance.', 1, 10),
  ('kindness', 'Smil til og hils på tre personer du møter', 'Smile at and greet three people you meet', 'Møt blikket, smil og hils på tre personer i løpet av dagen. På video kan du bruke kameraet og et varmt «hei».', 'Meet their eyes, smile and greet three people during the day. On video you can turn on your camera and say a warm “hi”.', 1, 10),
  ('kindness', 'Gjør noe felles litt ryddigere', 'Tidy something everyone shares', 'Ryd opp i noe alle bruker: pauserommet, en delt mappe eller en gammel tråd. Gjør det litt bedre enn du fant det.', 'Clean up something everyone uses: the break room, a shared folder or an old thread. Leave it a little better than you found it.', 1, 10),
  ('kindness', 'Send en varm hilsen til en kollega med travel uke', 'Send a warm note to a colleague with a busy week', 'Send noen en kort melding: «Jeg ser du har mye å gjøre. Lykke til, og si fra hvis jeg kan hjelpe.» Mer trenger det ikke være.', 'Send someone a short message: “I can see you have a lot on your plate. Good luck, and tell me if I can help.” It does not need to be more.', 1, 10),
  ('kindness', 'Tilby hjelp med en liten oppgave', 'Offer to help with a small task', 'Spør en kollega om det er noe lite du kan ta av hendene deres. Hjelp til på en konkret måte, og la dem si nei uten dårlig samvittighet.', 'Ask a colleague if there is something small you can take off their hands. Help in a concrete way, and let them say no without feeling bad.', 2, 20),
  ('kindness', 'Rose noen offentlig i teamets kanal', 'Praise someone publicly in the team channel', 'Skriv en anerkjennelse til en kollega i en felles kanal. Fortell hva de gjorde og hva det betydde for teamet.', 'Write an appreciation for a colleague in a shared channel. Say what they did and what it meant for the team.', 2, 20),
  ('kindness', 'Ta med en liten overraskelse til en kollega', 'Bring a colleague a small surprise', 'En klementin, en kopp te eller en pepperkake gjør nytte. Det skal være lite og hyggelig, ikke dyrt. På video kan du sende en digital hilsen i stedet.', 'A clementine, a cup of tea or a gingerbread cookie will do. It should be small and kind, not expensive. On video you can send a digital greeting instead.', 2, 20),
  ('kindness', 'Ta kontakt med noen du ikke har hørt fra på en stund', 'Reach out to someone you have not heard from in a while', 'Send en melding til en tidligere kollega eller noen du savner å snakke med. «Tenkte på deg, hvordan har du det?» er nok.', 'Send a message to a former colleague or someone you miss talking to. “Was thinking of you, how are you?” is enough.', 2, 20),
  ('kindness', 'Besvar et spørsmål ingen har svart på', 'Answer a question nobody has answered', 'Finn et ubesvart spørsmål i en intern kanal og ta deg tid til å hjelpe, selv om det ikke er ditt fagfelt. Pek gjerne på riktig person.', 'Find an unanswered question in an internal channel and take the time to help, even if it is outside your field. Pointing to the right person counts.', 2, 20),
  ('kindness', 'Skriv et julekort med noe konkret du setter pris på', 'Write a Christmas card with something specific you appreciate', 'Skriv et kort, på papir eller digitalt, til en kollega. Fortell én konkret ting du setter pris på ved å jobbe sammen med dem.', 'Write a card, on paper or digitally, to a colleague. Tell them one specific thing you appreciate about working with them.', 3, 30),
  ('kindness', 'Ta over en liten oppgave for en stresset kollega', 'Take over a small task for a stressed colleague', 'Hør hvem som har det travelt, og tilby å ta en avgrenset oppgave, for eksempel å skrive referat eller sjekke noe. Avtal tydelig hva du tar.', 'Listen for who is under pressure, and offer to take a clearly bounded task, such as writing minutes or checking something. Agree clearly on what you are taking.', 3, 30),
  ('learning', 'Lær en julehilsen på et nytt språk', 'Learn a Christmas greeting in a new language', 'Finn ut hvordan man sier «god jul» på et språk du ikke kan, og bruk det i dag. Spør gjerne en kollega som kan språket.', 'Find out how to say “merry Christmas” in a language you do not speak, and use it today. Ask a colleague who speaks it if you like.', 1, 10),
  ('learning', 'Les noe utenfor ditt fagfelt og fortell ett poeng', 'Read something outside your field and share one point', 'Les en kort artikkel om noe du vanligvis ikke bryr deg om, og fortell en kollega det mest interessante du fant.', 'Read a short article about something you do not usually care about, and tell a colleague the most interesting thing you found.', 1, 10),
  ('learning', 'Spør en kollega hva de egentlig jobber med', 'Ask a colleague what they actually work on', 'Spør noen om hva en vanlig dag i jobben deres består av. Lytt, og still ett oppfølgingsspørsmål.', 'Ask someone what a normal day in their job looks like. Listen, and ask one follow-up question.', 1, 10),
  ('learning', 'Lær et tastatursnarvei- eller verktøytriks og vis det', 'Learn a shortcut or tool trick and show it', 'Finn et triks som sparer deg tid i et verktøy du bruker daglig, og vis det til en kollega.', 'Find a trick that saves you time in a tool you use every day, and show it to a colleague.', 1, 10),
  ('learning', 'Finn ut hvorfor vi feirer Lucia', 'Find out why we celebrate Lucia', 'Les om Luciadagen 13. desember og hvor tradisjonen kommer fra. Fortell en kollega noe de ikke visste.', 'Read about Lucia day on 13 December and where the tradition comes from. Tell a colleague something they did not know.', 1, 10),
  ('learning', 'Be en kollega vise deg noe de er flink til', 'Ask a colleague to show you something they are good at', 'Spør om 15 minutter der en kollega viser deg en arbeidsoppgave eller metode de mestrer. Ta notater og si takk.', 'Ask for 15 minutes in which a colleague shows you a task or method they have mastered. Take notes and say thank you.', 2, 20),
  ('learning', 'Hør en podkast eller se en kort forelesning', 'Listen to a podcast or watch a short lecture', 'Bruk 20 minutter på noe du vil lære om, og del én ting du tar med deg med en kollega.', 'Spend 20 minutes on something you want to learn about, and share one takeaway with a colleague.', 2, 20),
  ('learning', 'Skriv ned tre ting du har lært i år', 'Write down three things you learned this year', 'Tenk tilbake på året og noter tre ting du har lært, store eller små. Del gjerne én med teamet.', 'Look back over the year and note three things you have learned, big or small. Share one with the team if you like.', 2, 20),
  ('learning', 'Ta en kort nettkurs-leksjon i noe du er nysgjerrig på', 'Take a short online lesson in something you are curious about', 'Velg en gratis leksjon på 10 til 15 minutter om et tema som lokker deg, fra språk til programmering til baking. Fortell hva du lærte.', 'Pick a free 10 to 15 minute lesson on a topic that tempts you, from languages to programming to baking. Tell someone what you learned.', 2, 20),
  ('learning', 'Lær deg «takk» og «hei» på tegnspråk', 'Learn “thank you” and “hello” in sign language', 'Finn en video som viser norsk tegnspråk, og lær noen enkle tegn. Vis dem til en kollega.', 'Find a video of Norwegian sign language and learn a few simple signs. Show them to a colleague.', 2, 20),
  ('learning', 'Hold en «lær meg på 10 minutter»', 'Give a “teach me in 10 minutes”', 'Lær bort noe du kan til en eller flere kollegaer på ti minutter, fysisk eller på video. Det kan være en jobbting eller en hobby.', 'Teach one or more colleagues something you know in ten minutes, in person or on video. It can be a work thing or a hobby.', 3, 30),
  ('learning', 'Be om råd fra en kollega med mer erfaring', 'Ask a more experienced colleague for advice', 'Be en erfaren kollega om 20 minutter og spør om råd om en utfordring eller en retning du vurderer. Si takk til slutt.', 'Ask an experienced colleague for 20 minutes and ask for advice on a challenge or a direction you are considering. Say thank you at the end.', 3, 30),
  ('collaboration', 'Spør en kollega om en mening', 'Ask a colleague for an opinion', 'Spør en kollega hva de tenker om noe du jobber med. Lytt til svaret, og si hva du tar med deg.', 'Ask a colleague what they think about something you are working on. Listen to the answer, and say what you take from it.', 1, 10),
  ('collaboration', 'Del et tips som kan hjelpe teamet', 'Share a tip that can help the team', 'Legg en nyttig lenke, et verktøy eller en erfaring i teamets kanal. Skriv en linje om hvorfor det er nyttig.', 'Post a useful link, tool or experience in the team channel. Write a line about why it is useful.', 1, 10),
  ('collaboration', 'Rett opp én utdatert ting i felles dokumentasjon', 'Fix one outdated thing in shared documentation', 'Finn en gammel instruks, en lenke som ikke virker eller en utdatert side, og fiks den. Små rettelser sparer mange.', 'Find an old instruction, a broken link or an outdated page, and fix it. Small corrections save many people time.', 1, 10),
  ('collaboration', 'Spør teamet hva de trenger hjelp med i dag', 'Ask the team what they need help with today', 'Skriv i teamets kanal: «Er det noe jeg kan hjelpe med i dag?» Følg opp hvis noen svarer.', 'Write in the team channel: “Is there anything I can help with today?” Follow up if someone answers.', 1, 10),
  ('collaboration', 'Hjelp noen med å finne riktig person eller informasjon', 'Help someone find the right person or information', 'Når noen lurer på hvor noe finnes eller hvem som vet, hjelp dem hele veien frem. Ta deg tid til å vise veien.', 'When someone wonders where something is or who knows, help them all the way. Take the time to show the way.', 1, 10),
  ('collaboration', 'Jobb sammen med en kollega i 30 minutter', 'Work with a colleague for 30 minutes', 'Slå dere sammen om én oppgave, side ved side eller på skjermdeling. Bytt på å styre.', 'Team up on one task, side by side or screen-sharing. Take turns leading.', 2, 20),
  ('collaboration', 'Forbedre én liten ting i en felles arbeidsmåte', 'Improve one small thing in how you work together', 'Foreslå og gjør en liten endring i en mal, en sjekkliste eller en møteform som gjør hverdagen enklere for flere.', 'Suggest and make a small change in a template, a checklist or a meeting format that makes everyday work easier for several people.', 2, 20),
  ('collaboration', 'Gi vennlig og konkret tilbakemelding på et utkast', 'Give kind and specific feedback on a draft', 'Les gjennom noe en kollega har bedt om innspill på. Si hva som fungerer, og kom med ett konkret forslag.', 'Read something a colleague has asked for input on. Say what works, and give one concrete suggestion.', 2, 20),
  ('collaboration', 'Be om hjelp med noe selv', 'Ask for help with something yourself', 'Samarbeid går begge veier. Be en kollega om hjelp med noe lite, og si tydelig hva du trenger.', 'Collaboration goes both ways. Ask a colleague for help with something small, and say clearly what you need.', 2, 20),
  ('collaboration', 'Skriv og del et kort referat', 'Write and share a short summary', 'Etter et møte eller en samtale: skriv tre til fem linjer om hva som ble bestemt og hvem som gjør hva, og del det.', 'After a meeting or conversation: write three to five lines on what was decided and who does what, and share it.', 2, 20),
  ('collaboration', 'Hold en 25 minutters felles ryddedugnad', 'Hold a 25-minute shared tidying session', 'Samle minst tre kollegaer og rydd noe felles i 25 minutter: innboksen, delte dokumenter eller pauserommet.', 'Gather at least three colleagues and tidy something shared for 25 minutes: the inbox, shared documents or the break room.', 3, 30),
  ('collaboration', 'Lag en kort guide for en nyansatt eller en kollega', 'Make a short guide for a new hire or a colleague', 'Skriv ned det du ville ønsket å vite som ny, eller lær opp en kollega i noe du kan, og lag en kort guide de kan bruke senere.', 'Write down what you wish you had known as a newcomer, or teach a colleague something you know, and make a short guide they can use later.', 3, 30),
  ('holiday_fun', 'Ha på deg nisselue eller noe rødt i dag', 'Wear a Santa hat or something red today', 'Ta på deg en nisselue, et rødt skjerf eller noe annet som minner om jul. På video funker det også.', 'Put on a nisse hat, a red scarf or anything else that reminds you of Christmas. It works on video too.', 1, 10),
  ('holiday_fun', 'Del din favorittjulesang', 'Share your favourite Christmas song', 'Sett på en julelåt du liker og del den i chatten. Hva er den beste? Kanskje en klassiker som «Deilig er jorden» eller «Musevisa».', 'Put on a Christmas song you like and share it in the chat. Which one is the best? Maybe a classic like “Deilig er jorden” or “Musevisa”.', 1, 10),
  ('holiday_fun', 'Fortell om en julematradisjon', 'Tell about a Christmas food tradition', 'Del en matradisjon du kjenner fra jul, fra din familie eller et sted du har bodd. Bare hvis du har lyst.', 'Share a food tradition you know from Christmas, from your family or somewhere you have lived. Only if you feel like it.', 1, 10),
  ('holiday_fun', 'Pynt skrivebordet eller videobakgrunnen litt', 'Decorate your desk or video background a little', 'Sett opp litt julepynt: en lykt, en grankvist, en liten nisse eller en bakgrunn til videomøter.', 'Put up a bit of Christmas decoration: a lantern, a sprig of spruce, a little nisse or a video-call background.', 1, 10),
  ('holiday_fun', 'Gi grøten et smørøye: fortell hvordan du spiser den', 'Give the porridge its butter eye: tell how you eat it', 'Risengrynsgrøt med kanel, sukker, smør eller saft? Del hvordan du liker grøten din i chatten, og se om noen er uenige.', 'Rice porridge with cinnamon, sugar, butter or juice? Share how you like your porridge in the chat, and see if anyone disagrees.', 1, 10),
  ('holiday_fun', 'Bak eller kjøp pepperkaker og del en', 'Bake or buy gingerbread and share one', 'Del en pepperkake med en kollega, eller send et bilde hvis dere jobber hjemmefra. Det er lov å kjøpe ferdig deig.', 'Share a gingerbread cookie with a colleague, or send a photo if you work from home. Store-bought dough is allowed.', 2, 20),
  ('holiday_fun', 'Lag en 10 minutters nisse-quiz', 'Make a 10-minute nisse quiz', 'Skriv fem spørsmål om norsk jul og nisser, og kjør dem med et par kollegaer, på video eller ved lunsjbordet.', 'Write five questions about Norwegian Christmas and nisser, and run them with a couple of colleagues, on video or at the lunch table.', 2, 20),
  ('holiday_fun', 'Skriv et lite julerim om teamet', 'Write a little Christmas rhyme about the team', 'Skriv fire linjer på rim om teamet eller arbeidsuken, og del dem. Det trenger ikke være bra, bare morsomt.', 'Write four rhyming lines about the team or the work week, and share them. They do not need to be good, just fun.', 2, 20),
  ('holiday_fun', 'Flett et julehjerte og vis det frem', 'Weave a paper Christmas heart and show it off', 'Klipp og flett et julehjerte av papir. Vis det frem på skrivebordet eller i chatten.', 'Cut and weave a paper Christmas heart. Show it off on your desk or in the chat.', 2, 20),
  ('holiday_fun', 'Gå en tur i vintermørket med lykt', 'Take a walk in the winter dark with a lantern', 'Ta en kveldstur med lommelykt eller lykt og la øynene hvile på stjernene. Del gjerne et bilde, eller bare nyt det.', 'Take an evening walk with a torch or lantern and let your eyes rest on the stars. Share a photo if you like, or just enjoy it.', 2, 20),
  ('holiday_fun', 'Arranger 15 minutters julesangstund', 'Organise a 15-minute carol session', 'Inviter til en liten stund med sang eller musikk, fysisk eller på video. Alle bestemmer selv om de vil synge.', 'Invite colleagues to a short moment of singing or music, in person or on video. Everyone decides for themselves whether to sing.', 3, 30),
  ('holiday_fun', 'Lag en nissedør eller nisseskulptur av ting du har', 'Build a nisse door or sculpture from what you have', 'Bygg en liten nissedør eller nisse av papir, binders og det du finner på kontoret, og vis den frem.', 'Build a small nisse door or nisse from paper, paper clips and whatever you find at the office, and show it off.', 3, 30);
